import pytest
from requests import Response

@pytest.mark.parametrize("pet_id, expected_status", [
    (1, 200),  # Valid pet ID
    (999999, 400),  # Invalid pet ID
])
def test_delete_pet(api_client, valid_api_key, pet_id, expected_status):
    """
    Test deleting a pet by ID.
    Covers valid and invalid pet ID scenarios.
    """
    headers = {"api_key": valid_api_key}
    endpoint = f"pet/{pet_id}"
    response: Response = api_client.api_helper.make_request(endpoint, headers=headers, method='DELETE')
    
    assert response.status_code == expected_status
    if response.status_code == 200:
        assert response.json().get("message") == "Pet deleted"
    elif response.status_code == 400:
        assert response.json().get("message") == "Invalid pet value"
    else:
        assert "Unexpected error" in response.json().get("message", "")

@pytest.mark.parametrize("api_key, expected_status", [
    (None, 401),  # Missing API key
    ("INVALID_API_KEY", 403),  # Invalid API key
])
def test_delete_pet_authentication(api_client, api_key, expected_status):
    """
    Test authentication scenarios for deleting a pet.
    Covers missing and invalid API key scenarios.
    """
    headers = {"api_key": api_key} if api_key else {}
    endpoint = "pet/1"
    response: Response = api_client.api_helper.make_request(endpoint, headers=headers, method='DELETE')
    
    assert response.status_code == expected_status
    if response.status_code == 401:
        assert "Missing authentication" in response.json().get("message", "")
    elif response.status_code == 403:
        assert "Invalid credentials" in response.json().get("message", "")

